.trenespop button{cursor:pointer;color:var(--tp-ink)}
.trenespop button:focus-visible,.trenespop select:focus-visible,.trenespop input:focus-visible,.trenespop-modal button:focus-visible,.trenespop-modal input:focus-visible{outline:3px solid #3dd2ba;outline-offset:3px}
